package dev.ledgerbank.movement;
import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.core.convert.converter.Converter;import org.springframework.security.authentication.AbstractAuthenticationToken;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.oauth2.core.*;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.security.web.SecurityFilterChain;
@Configuration class SecurityConfig{
 @Bean JwtDecoder decoder(@Value("${ledgerbank.jwk-set-uri}")String uri){NimbusJwtDecoder decoder=NimbusJwtDecoder.withJwkSetUri(uri).build();decoder.setJwtValidator(validator());return decoder;}
 @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{Converter<Jwt,AbstractAuthenticationToken>c=j->{List<SimpleGrantedAuthority>a=new ArrayList<>();List<String>r=j.getClaimAsStringList("roles");if(r!=null)r.forEach(x->a.add(new SimpleGrantedAuthority("ROLE_"+x)));return new JwtAuthenticationToken(j,a,j.getSubject());};return h.csrf(x->x.disable()).sessionManagement(x->x.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(x->x.requestMatchers("/actuator/health/**","/actuator/prometheus").permitAll().requestMatchers("/api/v1/ops/**").hasRole("OPERATOR").requestMatchers("/api/v1/transfers/**").hasRole("CUSTOMER").anyRequest().denyAll()).oauth2ResourceServer(x->x.jwt(j->j.jwtAuthenticationConverter(c))).build();}
 private OAuth2TokenValidator<Jwt>validator(){OAuth2TokenValidator<Jwt>issuer=JwtValidators.createDefaultWithIssuer("ledgerbank-identity");OAuth2TokenValidator<Jwt>audience=jwt->jwt.getAudience().contains("ledgerbank-api")?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(new OAuth2Error("invalid_token","Required audience is missing",null));return new DelegatingOAuth2TokenValidator<>(issuer,audience);}
}
